#include <torch/extension.h>
torch::Tensor conv2d_forward(torch::Tensor x,
                             torch::Tensor weight,
                             c10::optional<torch::Tensor> bias,
                             int stride_h, int stride_w,
                             int pad_h, int pad_w,
                             int dilation_h, int dilation_w);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <c10/cuda/CUDAGuard.h>
#include <cute/tensor.hpp>
#include <cstdint>
#include <climits>

using namespace cute;

__global__ void conv2d_forward_kernel(
    const float* __restrict__ X,
    const float* __restrict__ W,
    const float* __restrict__ B,
    float* __restrict__ Y,
    int C, int H, int W_in,
    int OC, int KH, int KW,
    int Hout, int Wout,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dilation_h, int dilation_w,
    int tile_h, int tile_w,
    int w_tiles)
{
  constexpr int THREADS       = 256;
  constexpr int OC_TILE       = 16;
  constexpr int OUT_H_TILE    = 16;
  constexpr int OUT_W_TILE    = 32;
  constexpr int POINTS_PER_TH = 2;
  constexpr int C_CHUNK       = 4;

  const int tid = threadIdx.x;

  const int n = blockIdx.z;
  const int oc_base = blockIdx.y * OC_TILE;

  const int spatial_tile = blockIdx.x;
  const int oh_tile = spatial_tile / w_tiles;
  const int ow_tile = spatial_tile - oh_tile * w_tiles;
  const int oh_base = oh_tile * OUT_H_TILE;
  const int ow_base = ow_tile * OUT_W_TILE;

  const int64_t x_batch_stride = (int64_t)C * H * W_in;
  const int64_t y_batch_stride = (int64_t)OC * Hout * Wout;

  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * x_batch_stride),
      make_shape(C, H, W_in),
      make_stride((int64_t)H * W_in, (int64_t)W_in, Int<1>{})
  );

  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(OC, C, KH, KW),
      make_stride((int64_t)C * KH * KW,
                  (int64_t)KH * KW,
                  (int64_t)KW,
                  Int<1>{})
  );

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * y_batch_stride),
      make_shape(OC, Hout, Wout),
      make_stride((int64_t)Hout * Wout, (int64_t)Wout, Int<1>{})
  );

  extern __shared__ float smem_raw[];

  const int sw_elems = C_CHUNK * KH * KW * OC_TILE;
  float* sW_ptr = smem_raw;
  float* sX_ptr = smem_raw + sw_elems;

  auto sW = make_tensor(
      make_smem_ptr(sW_ptr),
      make_shape(Int<C_CHUNK>{}, KH, KW, Int<OC_TILE>{}),
      make_stride(KH * KW * OC_TILE, KW * OC_TILE, OC_TILE, Int<1>{})
  );

  auto sX = make_tensor(
      make_smem_ptr(sX_ptr),
      make_shape(Int<C_CHUNK>{}, tile_h, tile_w),
      make_stride(tile_h * tile_w, tile_w, Int<1>{})
  );

  int oh[POINTS_PER_TH];
  int ow[POINTS_PER_TH];
  int local_h0[POINTS_PER_TH];
  int local_w0[POINTS_PER_TH];
  bool valid[POINTS_PER_TH];

  #pragma unroll
  for (int i = 0; i < POINTS_PER_TH; ++i) {
    const int p = tid + i * THREADS;
    const int local_oh = p / OUT_W_TILE;
    const int local_ow = p - local_oh * OUT_W_TILE;

    oh[i] = oh_base + local_oh;
    ow[i] = ow_base + local_ow;
    local_h0[i] = local_oh * stride_h;
    local_w0[i] = local_ow * stride_w;
    valid[i] = (oh[i] < Hout) && (ow[i] < Wout);
  }

  float bias_values[OC_TILE];
  #pragma unroll
  for (int oc = 0; oc < OC_TILE; ++oc) {
    const int oc_global = oc_base + oc;
    bias_values[oc] = (B != nullptr && oc_global < OC) ? B[oc_global] : 0.0f;
  }

  float acc[POINTS_PER_TH][OC_TILE];
  #pragma unroll
  for (int i = 0; i < POINTS_PER_TH; ++i) {
    #pragma unroll
    for (int oc = 0; oc < OC_TILE; ++oc) {
      acc[i][oc] = bias_values[oc];
    }
  }

  const int tile_elems = tile_h * tile_w;
  const int weight_elems = C_CHUNK * KH * KW * OC_TILE;
  const int weight_per_c = KH * KW * OC_TILE;

  const int input_tile_h0 = oh_base * stride_h - pad_h;
  const int input_tile_w0 = ow_base * stride_w - pad_w;

  for (int c0 = 0; c0 < C; c0 += C_CHUNK) {
    #pragma unroll
    for (int cc = 0; cc < C_CHUNK; ++cc) {
      const int c = c0 + cc;
      if (c < C) {
        for (int idx = tid; idx < tile_elems; idx += THREADS) {
          const int lh = idx / tile_w;
          const int lw = idx - lh * tile_w;
          const int ih = input_tile_h0 + lh;
          const int iw = input_tile_w0 + lw;

          float value = 0.0f;
          if ((unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)W_in) {
            value = mX(c, ih, iw);
          }
          sX(cc, lh, lw) = value;
        }
      }
    }

    for (int idx = tid; idx < weight_elems; idx += THREADS) {
      const int cc = idx / weight_per_c;
      int rem = idx - cc * weight_per_c;
      const int tap = rem / OC_TILE;
      const int oc = rem - tap * OC_TILE;
      const int kh = tap / KW;
      const int kw = tap - kh * KW;

      const int c = c0 + cc;
      const int oc_global = oc_base + oc;

      float value = 0.0f;
      if (c < C && oc_global < OC) {
        value = mW(oc_global, c, kh, kw);
      }
      sW(cc, kh, kw, oc) = value;
    }

    __syncthreads();

    #pragma unroll
    for (int cc = 0; cc < C_CHUNK; ++cc) {
      const int c = c0 + cc;
      if (c >= C) {
        break;
      }

      #pragma unroll 5
      for (int kh = 0; kh < KH; ++kh) {
        int lh[POINTS_PER_TH];

        #pragma unroll
        for (int i = 0; i < POINTS_PER_TH; ++i) {
          lh[i] = local_h0[i] + kh * dilation_h;
        }

        #pragma unroll 9
        for (int kw = 0; kw < KW; ++kw) {
          float w_values[OC_TILE];

          #pragma unroll
          for (int oc = 0; oc < OC_TILE; ++oc) {
            w_values[oc] = sW(cc, kh, kw, oc);
          }

          #pragma unroll
          for (int i = 0; i < POINTS_PER_TH; ++i) {
            if (valid[i]) {
              const int lw = local_w0[i] + kw * dilation_w;
              const float x_value = sX(cc, lh[i], lw);

              #pragma unroll
              for (int oc = 0; oc < OC_TILE; ++oc) {
                acc[i][oc] += x_value * w_values[oc];
              }
            }
          }
        }
      }
    }

    __syncthreads();
  }

  #pragma unroll
  for (int i = 0; i < POINTS_PER_TH; ++i) {
    if (valid[i]) {
      #pragma unroll
      for (int oc = 0; oc < OC_TILE; ++oc) {
        const int oc_global = oc_base + oc;
        if (oc_global < OC) {
          mY(oc_global, oh[i], ow[i]) = acc[i][oc];
        }
      }
    }
  }
}

torch::Tensor conv2d_forward(torch::Tensor x,
                             torch::Tensor weight,
                             c10::optional<torch::Tensor> bias,
                             int stride_h, int stride_w,
                             int pad_h, int pad_w,
                             int dilation_h, int dilation_w)
{
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
  TORCH_CHECK(x.dim() == 4, "x must have shape [N, C, H, W]");
  TORCH_CHECK(weight.dim() == 4, "weight must have shape [OC, C, KH, KW]");
  TORCH_CHECK(stride_h > 0 && stride_w > 0, "stride values must be positive");
  TORCH_CHECK(pad_h >= 0 && pad_w >= 0, "padding values must be non-negative");
  TORCH_CHECK(dilation_h > 0 && dilation_w > 0, "dilation values must be positive");

  const c10::cuda::CUDAGuard device_guard(x.device());

  auto x_c = x.contiguous();
  auto weight_c = weight.contiguous();

  const int64_t N = x_c.size(0);
  const int64_t C = x_c.size(1);
  const int64_t H = x_c.size(2);
  const int64_t W_in = x_c.size(3);

  const int64_t OC = weight_c.size(0);
  const int64_t C_w = weight_c.size(1);
  const int64_t KH = weight_c.size(2);
  const int64_t KW = weight_c.size(3);

  TORCH_CHECK(C_w == C, "weight input-channel dimension must match x");
  TORCH_CHECK(KH > 0 && KW > 0, "kernel dimensions must be positive");
  TORCH_CHECK(N <= INT_MAX && C <= INT_MAX && H <= INT_MAX && W_in <= INT_MAX,
              "input dimensions are too large");
  TORCH_CHECK(OC <= INT_MAX && KH <= INT_MAX && KW <= INT_MAX,
              "weight dimensions are too large");

  torch::Tensor bias_c;
  const float* bias_ptr = nullptr;
  if (bias.has_value()) {
    bias_c = bias.value().contiguous();
    TORCH_CHECK(bias_c.is_cuda(), "bias must be a CUDA tensor");
    TORCH_CHECK(bias_c.scalar_type() == at::kFloat, "bias must be float32");
    TORCH_CHECK(bias_c.dim() == 1 && bias_c.size(0) == OC,
                "bias must have shape [OC]");
    bias_ptr = bias_c.data_ptr<float>();
  }

  const int64_t Hout =
      (H + 2 * (int64_t)pad_h - (int64_t)dilation_h * (KH - 1) - 1) /
      stride_h + 1;
  const int64_t Wout =
      (W_in + 2 * (int64_t)pad_w - (int64_t)dilation_w * (KW - 1) - 1) /
      stride_w + 1;

  TORCH_CHECK(Hout > 0 && Wout > 0, "computed output dimensions must be positive");
  TORCH_CHECK(Hout <= INT_MAX && Wout <= INT_MAX,
              "output dimensions are too large");

  auto y = torch::empty({N, OC, Hout, Wout}, x_c.options());
  if (N == 0 || OC == 0) {
    return y;
  }

  constexpr int THREADS = 256;
  constexpr int OC_TILE = 16;
  constexpr int OUT_H_TILE = 16;
  constexpr int OUT_W_TILE = 32;
  constexpr int C_CHUNK = 4;

  const int64_t tile_h =
      (OUT_H_TILE - 1) * (int64_t)stride_h +
      (int64_t)dilation_h * (KH - 1) + 1;
  const int64_t tile_w =
      (OUT_W_TILE - 1) * (int64_t)stride_w +
      (int64_t)dilation_w * (KW - 1) + 1;

  TORCH_CHECK(tile_h > 0 && tile_w > 0, "invalid shared-memory tile size");
  TORCH_CHECK(tile_h <= INT_MAX && tile_w <= INT_MAX,
              "shared-memory tile dimensions are too large");

  const int64_t sx_elems = (int64_t)C_CHUNK * tile_h * tile_w;
  const int64_t sw_elems = (int64_t)C_CHUNK * KH * KW * OC_TILE;
  TORCH_CHECK(sx_elems <= INT_MAX && sw_elems <= INT_MAX,
              "shared-memory tensors are too large");

  const size_t smem_bytes = (size_t)(sx_elems + sw_elems) * sizeof(float);

  if (smem_bytes > 48 * 1024) {
    int device = 0;
    cudaError_t err = cudaGetDevice(&device);
    TORCH_CHECK(err == cudaSuccess, cudaGetErrorString(err));

    int max_smem = 0;
    err = cudaDeviceGetAttribute(
        &max_smem, cudaDevAttrMaxSharedMemoryPerBlockOptin, device);
    TORCH_CHECK(err == cudaSuccess, cudaGetErrorString(err));
    TORCH_CHECK(smem_bytes <= (size_t)max_smem,
                "required dynamic shared memory exceeds device limit");

    err = cudaFuncSetAttribute(
        conv2d_forward_kernel,
        cudaFuncAttributeMaxDynamicSharedMemorySize,
        (int)smem_bytes);
    TORCH_CHECK(err == cudaSuccess, cudaGetErrorString(err));
  }

  const int64_t h_tiles = (Hout + OUT_H_TILE - 1) / OUT_H_TILE;
  const int64_t w_tiles = (Wout + OUT_W_TILE - 1) / OUT_W_TILE;
  const int64_t oc_tiles = (OC + OC_TILE - 1) / OC_TILE;
  const int64_t spatial_tiles = h_tiles * w_tiles;

  TORCH_CHECK(spatial_tiles <= INT_MAX, "too many spatial tiles");
  TORCH_CHECK(oc_tiles <= 65535, "too many output-channel tiles");
  TORCH_CHECK(N <= 65535, "batch size is too large for this kernel launch");

  dim3 block(THREADS);
  dim3 grid((unsigned)spatial_tiles, (unsigned)oc_tiles, (unsigned)N);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv2d_forward_kernel<<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      weight_c.data_ptr<float>(),
      bias_ptr,
      y.data_ptr<float>(),
      (int)C, (int)H, (int)W_in,
      (int)OC, (int)KH, (int)KW,
      (int)Hout, (int)Wout,
      stride_h, stride_w,
      pad_h, pad_w,
      dilation_h, dilation_w,
      (int)tile_h, (int)tile_w,
      (int)w_tiles
  );

  cudaError_t err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess,
              "conv2d_forward_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

conv2d_ext = load_inline(
    name="cute_tiled_conv2d_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
